package app.onklav.home
import android.app.Application
import androidx.test.core.app.ApplicationProvider
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config
import java.time.*
import java.io.File
@RunWith(RobolectricTestRunner::class) @Config(sdk=[29])
class CalendarTest{
 private fun event(start:String="2026-03-07T09:00",repeat:String="none")=CalendarEvent(title="Test event",start=LocalDateTime.parse(start),end=LocalDateTime.parse(start).plusHours(1),zone="America/Chicago",repeat=repeat,updated=0)
 private fun range(e:CalendarEvent,a:String,b:String)=CalendarRules.occurrences(e,LocalDate.parse(a).atStartOfDay(ZoneOffset.UTC).toInstant(),LocalDate.parse(b).atStartOfDay(ZoneOffset.UTC).toInstant())
 @Test fun recurringLocalTimesSurviveDstAndMidnightRanges(){val e=event(repeat="daily");val rows=range(e,"2026-03-07","2026-03-11");assertEquals(4,rows.size);assertTrue(rows.all{it.start.hour==9});assertEquals(23,Duration.between(rows[0].start,rows[1].start).toHours());assertEquals(24,Duration.between(rows[1].start,rows[2].start).toHours());val overnight=e.copy(repeat="none",start=LocalDateTime.parse("2026-03-07T23:00"),end=LocalDateTime.parse("2026-03-08T02:00"));assertEquals(1,range(overnight,"2026-03-08","2026-03-09").size)}
 @Test fun springGapNeverCreatesAZeroLengthOccurrence(){val e=event("2026-03-08T02:30","daily");val o=range(e,"2026-03-08","2026-03-09").single();assertTrue(o.end.toInstant()>o.start.toInstant())}
 @Test fun monthlySkipsMissingDatesAndYearlySkipsNonLeapYears(){assertEquals(listOf(1,3,5),range(event("2026-01-31T10:00","monthly"),"2026-01-01","2026-06-01").map{it.date.monthValue});assertEquals(listOf(2024,2028),range(event("2024-02-29T10:00","yearly"),"2024-01-01","2029-01-01").map{it.date.year})}
 @Test fun weeklyIntervalExclusionsAndInclusiveRepeatEnd(){val e=event("2026-01-05T09:00","weekly").copy(interval=2,weekdays=1 or 4,until=LocalDate.parse("2026-01-21"),excluded=setOf(LocalDate.parse("2026-01-07")));assertEquals(listOf("2026-01-05","2026-01-19","2026-01-21"),range(e,"2026-01-01","2026-02-01").map{it.date.toString()})}
 @Test fun oldRecurrencesJumpToRequestedWindowAndLimitsAreApplied(){val rows=range(event("1900-01-01T09:00","daily"),"2199-01-01","2199-01-04");assertEquals(3,rows.size);assertEquals(2199,rows.first().date.year)}
 @Test fun overlapColumnsResetAfterEachConflictGroup(){val a=event("2026-06-01T09:00");val b=a.copy(id=java.util.UUID.randomUUID().toString(),start=a.start.plusMinutes(30),end=a.end.plusMinutes(30));val c=a.copy(id=java.util.UUID.randomUUID().toString(),start=a.start.plusHours(3),end=a.end.plusHours(3));val rows=listOf(a,b,c).flatMap{range(it,"2026-06-01","2026-06-02")};val layout=CalendarRules.layout(rows);assertEquals(listOf(2,2,1),layout.map{it.columns});assertEquals(listOf(0,1,0),layout.map{it.column})}
 @Test fun allDayIsFloatingAndEndIsExclusive(){val e=event("2026-06-01T00:00").copy(allDay=true,end=LocalDateTime.parse("2026-06-04T00:00"));assertEquals(1,range(e,"2026-06-03","2026-06-04").size);val rows=CalendarRules.between(listOf(e),LocalDate.parse("2026-06-04"),LocalDate.parse("2026-06-05"),listOf(CalendarBook()),ZoneId.of("Asia/Tokyo"));assertTrue(rows.isEmpty())}
 @Test fun fiveReminderLimitAndValidationAreStrict(){event().copy(reminders=listOf(5,15,60,1440,4320).map{CalendarReminder(it)}).validate();for(e in listOf(event().copy(reminders=List(6){CalendarReminder(it)}),event().copy(reminders=listOf(CalendarReminder(5),CalendarReminder(5,true))),event().copy(end=event().start),event().copy(zone="bad zone"))){assertThrows(Exception::class.java){e.validate()}}}
 @Test fun reminderPlanSeparatesSoundAndSkipsDeliveredAndStaleTimes(){val e=event("2026-06-01T09:00","daily").copy(reminders=listOf(CalendarReminder(15,false),CalendarReminder(5,true)));val now=Instant.parse("2026-06-01T13:44:00Z").toEpochMilli();val plans=CalendarReminders.plan(CalendarState(events=listOf(e)),now,emptySet());assertEquals(2,plans.size);assertFalse(plans[0].sound);assertTrue(plans[1].sound);assertEquals(Instant.parse("2026-06-01T13:45:00Z").toEpochMilli(),plans[0].at);val next=CalendarReminders.plan(CalendarState(events=listOf(e)),now,setOf(plans[0].key));assertTrue(next.first{!it.sound}.at>plans[0].at);assertEquals(plans.map{it.at},CalendarReminders.plan(CalendarState(events=listOf(e.copy(updated=now+86400000))),now,emptySet()).map{it.at})}
 @Test fun calendarStateRoundTripsAndCorruptionDoesNotBecomeEmpty(){val app=ApplicationProvider.getApplicationContext<Application>();val dir=File(app.cacheDir,"calendar-data-test").apply{deleteRecursively();mkdirs()};val c=object:android.content.ContextWrapper(app){override fun getFilesDir()=dir};val disk=CalendarDisk(c);val state=CalendarState(events=listOf(event()));disk.write(state);assertEquals(state,disk.read());File(dir,"calendar/events.json").writeText("broken");assertThrows(Exception::class.java){disk.read()};dir.deleteRecursively()}
 @Test fun icsRoundTripKeepsZonesRecurrenceEscapesAndReminders(){val e=event("2026-06-01T09:00","weekly").copy(title="Lunch, tea; café",notes="First\nSecond\\third",weekdays=5,until=LocalDate.parse("2026-09-01"),excluded=setOf(LocalDate.parse("2026-06-03")),reminders=listOf(CalendarReminder(5,true),CalendarReminder(1440,false)));val text=CalendarIcs.export(listOf(e));val imported=CalendarIcs.parse(text);assertEquals(0,imported.skipped);val copy=imported.events.single();assertEquals(e.title,copy.title);assertEquals(e.start,copy.start);assertEquals(e.zone,copy.zone);assertEquals(e.excluded,copy.excluded);assertEquals(e.notes,copy.notes);assertEquals(e.reminders,copy.reminders);assertEquals(e.until,copy.until);assertEquals(e.weekdays,copy.weekdays)}
 @Test fun icsRejectsUnsupportedRecurrenceInsteadOfChangingItSilently(){val text=CalendarIcs.export(listOf(event(repeat="weekly"))).replace("FREQ=WEEKLY;INTERVAL=1;BYDAY=SA","FREQ=MONTHLY;BYDAY=2MO");val result=CalendarIcs.parse(text);assertEquals(1,result.skipped);assertTrue(result.events.isEmpty());assertThrows(Exception::class.java){CalendarIcs.parse("BEGIN:VCALENDAR\nBEGIN:VEVENT\n")}}
 @Test fun countedImportsPreserveExactOccurrenceCount(){val e=event("2026-01-31T10:00","monthly");val text=CalendarIcs.export(listOf(e)).replace("FREQ=MONTHLY;INTERVAL=1","FREQ=MONTHLY;COUNT=3");val result=CalendarIcs.parse(text);assertEquals(0,result.skipped);assertEquals(3,range(result.events.single(),"2026-01-01","2027-01-01").size);assertEquals(LocalDate.parse("2026-05-31"),result.events.single().until)}
 @Test fun fullSupportedEventSetCanBeExportedAndReimported(){val base=event().copy(notes=",".repeat(300),reminders=emptyList());val events=List(CalendarIcs.MAX_EVENTS){i->base.copy(id="event-$i",uid="event-$i",title="Event $i")};assertTrue(CalendarState(events=events).json().toString().toByteArray().size<8_000_000);val text=CalendarIcs.export(events);assertTrue(text.toByteArray().size>4_000_000);val restored=CalendarIcs.parse(text);assertEquals(0,restored.skipped);assertEquals(events.size,restored.events.size);assertEquals(events.last().notes,restored.events.last().notes)}
 @Test fun allDayCalendarExportPreservesDateRange(){val e=event("2026-06-01T00:00").copy(allDay=true,end=LocalDateTime.parse("2026-06-05T00:00"));val restored=CalendarIcs.parse(CalendarIcs.export(listOf(e))).events.single();assertTrue(restored.allDay);assertEquals(e.start,restored.start);assertEquals(e.end,restored.end)}
}
